import AddLiquidityConfirmModal from '@/components/liquidity/dlmm/AddLiquidityConfirmModal'
import useAddDlmmLiquidity from '@/hooks/dlmm/useAddDlmmLiquidity'
import useAddDlmmLiquidityButton from '@/hooks/dlmm/useAddDlmmLiquidityButton'
import useDlmmDeposit from '@/hooks/dlmm/useDlmmDeposit'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Token } from '@cetus/types'
import { isAvailableObject } from '@cetus/utils'
import NFTModal from '../NFTModal'
import H5Deposit from './H5'
import PCDeposit from './PC'

import Tour from '@/components/common/Tour'
import useTutorial from '@/hooks/dlmm/useTutorial'
import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore from '@/store/dlmm/addDlmmLiquidity'
import useZapStore from '@/store/zap/index'

interface RangeTab {
  label: string
  key: string
  imgInfo: {
    src: string | undefined
    w: string
    h: string
    borderRadius: string
    fallbackSrc: string
  }
}

interface FeeTier {
  title: string
  feeDisplay: string
  feeRate: string
  poolAddress: string
  tvl: unknown
}

interface DLMMDepositProps<T extends RangeTab = RangeTab> {
  rangeTabList: T[]
  binStep: number
  baseFee: string
  getList: () => Promise<void>
  getPrice: () => Promise<void>
}

function DLMMDeposit<T extends RangeTab, K extends FeeTier>({ rangeTabList, binStep, baseFee, getList, getPrice }: DLMMDepositProps<T>) {
  const { dlmmApiPoolInfo, dlmmContractPoolInfo } = useDlmmLiquidityStore()
  const { fromToken, toToken, setFromToken, setToToken } = useAddDlmmLiquidityStore()
  const { zapAmount, currentZapToken } = useZapStore()
  const { direct, perText, onReverseClick, currentRangeTab } = useDlmmDeposit<T>({
    rangeTabList
  })
  const {
    handleAmountChange,
    byAmountIn,
    setByAmountIn,
    fromAmount,
    fromAmountValue,
    setFromAmount,
    toAmount,
    toAmountValue,
    setToAmount,
    liquidityAmount,
    fromBalanceInfo,
    toBalanceInfo,
    totalAmount,
    fromTokenLock,
    toTokenLock,
    handleAdd,
    confirmModalOpen,
    setConfirmModalOpen,
    nftOpen,
    setNftOpen,
    relatedPosId,
    handleSubmit
  } = useAddDlmmLiquidity(direct)

  const { btnText, btnDisabled } = useAddDlmmLiquidityButton()

  const { isApp } = useWindowWidth()
  const props = {
    btnText,
    btnDisabled,
    onReverseClick,
    direct,
    perText,
    rangeTabList,
    currentRangeTab,
    fromBalanceInfo,
    toBalanceInfo,
    fromAmountValue,
    toAmountValue,
    handleAmountChange,
    handleAdd,
    handleSubmit
  }
  const { stepMap, showPoolTutorial, onTutorialExit, onTutorialNext, onTutorialPrevious, dlmmTutorialStep } = useTutorial()
  return (
    <>
      {isApp ? <H5Deposit {...props} /> : <PCDeposit {...props} />}
      {confirmModalOpen && (
        <AddLiquidityConfirmModal onClose={() => setConfirmModalOpen(false)} data={{ baseFee: baseFee as any }} onSubmit={handleSubmit} />
      )}

      {nftOpen && relatedPosId && isAvailableObject(dlmmApiPoolInfo) && (
        <NFTModal
          onClose={() => setNftOpen(false)}
          tokenA={fromToken as Token}
          tokenB={toToken as Token}
          posId={relatedPosId}
          fee={dlmmApiPoolInfo?.base_fee_rate as string}
          isReverse={false}
        />
      )}
      {showPoolTutorial && (
        <Tour
          isOpen={showPoolTutorial}
          step={stepMap[dlmmTutorialStep]}
          onExit={onTutorialExit}
          onNext={onTutorialNext}
          onPrev={onTutorialPrevious}
        />
      )}
    </>
  )
}

export default DLMMDeposit
