import TotalAmount from '@/components/common/TotalAmount'
import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore from '@/store/dlmm/addDlmmLiquidity'
import { TradeInputGroup } from '@cetus/design'
import useQueryParams from '@cetus/hooks/src/useQueryParams'
import { d } from '@cetus/utils'
import { Box, Button, HStack, Text, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import AutoFillSwitch from '../AutoFillSwitch'
import SelectStrategy from '../SelectStrategy'
import SetPriceRange from '../SetPriceRange'
import { DLMMDepositProps } from './type'

function PCDeposit({
  btnText,
  btnDisabled,
  onReverseClick,
  direct,
  perText,
  rangeTabList,
  currentRangeTab,
  handleAmountChange,
  fromAmountValue,
  toAmountValue,
  fromBalanceInfo,
  toBalanceInfo,
  handleAdd
}: DLMMDepositProps<any>) {
  const { dlmmApiPoolInfo } = useDlmmLiquidityStore()
  const {
    fromToken,
    toToken,
    fromAmount,
    toAmount,
    byAmountIn,
    totalAmount,
    fromTokenLock,
    toTokenLock,
    minPriceData,
    maxPriceData,
    positionCount,
    numBins
  } = useAddDlmmLiquidityStore()

  const { poolId } = useQueryParams()
  const priceImpactBasedOnMarket = '0.1'
  const priceImpactBasedOnMarketDisplay = useMemo(() => {
    if (priceImpactBasedOnMarket && d(priceImpactBasedOnMarket).abs().gte(30)) {
      if (d(priceImpactBasedOnMarket).gte(30)) {
        return `+${d(priceImpactBasedOnMarket).toFixed(0)}%`
      }
      return `${d(priceImpactBasedOnMarket).toFixed(0)}%`
    }
    return undefined
  }, [priceImpactBasedOnMarket])

  return (
    <>
      <HStack gap="12px" align="flex-start">
        <VStack flex="1" minW="588px">
          <SetPriceRange
            perText={perText}
            direct={direct}
            minPriceData={minPriceData}
            maxPriceData={maxPriceData}
            rangeTabList={rangeTabList}
            currentRangeTab={currentRangeTab}
            onReverseClick={onReverseClick}
          />
        </VStack>
        <VStack gap="24px" minW="420px" maxW="460px" w="460px" p="18px 16px 16px" bg="card_bg" borderRadius="16px" align="flex-start">
          <VStack className="dlmm-tutorial-step-4" align="flex-start" gap="16px">
            <Text lineHeight="20px" fontSize="16px" fontWeight="500" color="text_caption">
              Select Strategy
            </Text>
            <SelectStrategy />
          </VStack>

          <VStack w="100%">
            <VStack gap="16px" w="100%" className="dlmm-tutorial-step-3" p="0 0 2px">
              <HStack w="100%" h="32px" justify="space-between">
                <Text lineHeight="20px" fontSize="16px" fontWeight="500" color="text_caption">
                  Deposit Amounts
                </Text>
                <HStack>
                  <AutoFillSwitch disabled={fromTokenLock || toTokenLock} />
                </HStack>
              </HStack>
              <Box w="100%" position="relative">
                <TradeInputGroup
                  onClick={onReverseClick}
                  from={{
                    wrapStyle: { h: '108px' },
                    balance: fromBalanceInfo?.balanceFormat || '',
                    value: fromAmount,
                    amountValue: fromAmountValue,
                    loading: false,
                    onChange: value => {
                      handleAmountChange(value, true, fromToken?.coin_type === dlmmApiPoolInfo?.coin_type_a)
                    },
                    selectable: false,
                    placeholder: '0.0',
                    token: fromToken,
                    onFocusChange: (focus: boolean) => {
                      if (focus && +(fromAmount + '') && !byAmountIn) {
                        handleAmountChange(fromAmount + '', true, fromToken?.coin_type === dlmmApiPoolInfo?.coin_type_b)
                      }
                    },
                    lock: {
                      isLock: fromTokenLock && !toTokenLock,
                      text: 'The current price is outside your specified price range. Single-asset deposit only.'
                    },
                    balancePosition: 'bottom'
                  }}
                  to={{
                    wrapStyle: { h: '108px' },
                    balance: toBalanceInfo?.balanceFormat || '',
                    value: toAmount,
                    amountValue: toAmountValue,
                    loading: false,
                    onFocusChange: (focus: boolean) => {
                      if (focus && +(toAmount + '') && byAmountIn) {
                        handleAmountChange(toAmount + '', false, toToken?.coin_type === dlmmApiPoolInfo?.coin_type_a)
                      }
                    },
                    onChange: value => {
                      handleAmountChange(value, false, toToken?.coin_type === dlmmApiPoolInfo?.coin_type_b)
                    },
                    selectable: false,
                    placeholder: '0.0',
                    token: toToken,
                    lock: {
                      isLock: !fromTokenLock && toTokenLock,
                      text: 'The current price is outside your specified price range. Single-asset deposit only.'
                    },
                    balancePosition: 'bottom'
                  }}
                  iconParams={{
                    xlinkHref: '#icon-icon_add',
                    svgFill: 'text_caption'
                  }}
                  lock={{
                    isLock: fromTokenLock && toTokenLock,
                    style: { h: '224px' }
                  }}
                />
              </Box>
            </VStack>
            <VStack w="100%" gap="8px" className="dlmm-tutorial-step-6" p="2px 8px 0px">
              {!!dlmmApiPoolInfo?.id && !(fromTokenLock && toTokenLock) && (
                <VStack gap="12px" w="100%" borderRadius="16px">
                  <Button
                    w="100%"
                    h="52px"
                    margin="-1px -1px 5px"
                    fontSize="18px"
                    fontWeight="500"
                    borderRadius="12px"
                    isDisabled={btnDisabled}
                    isLoading={false}
                    onClick={handleAdd}
                  >
                    {btnText}
                  </Button>

                  {fromToken && toToken && (
                    <>
                      {/* {positionCount > 1 && (
                        <HTextLabelBox
                          label={
                            <HStack gap="4px">
                              <Text>Position</Text>
                              <CetusTooltip
                                tooltip={
                                  <Text lineHeight="20px" fontSize="12px">
                                    Each position covers up to 69 bins on Sui, multiple positions are needed to cover a larger range.
                                  </Text>
                                }
                              >
                                <Icon xlinkHref="#icon-icon_tips" />
                              </CetusTooltip>
                            </HStack>
                          }
                          value={positionCount + ''}
                          labelStyle={{
                            fontSize: '14px'
                          }}
                          valueStyle={{
                            fontSize: '14px'
                          }}
                        />
                      )} */}

                      <TotalAmount totalAmount={totalAmount} loading={false} valueStyle={{ h: '20px', lineHeight: '20px' }} />

                      {/* {apiPoolInfo?.haveFarming && (
                        <AutoStakePosition disabled={fromTokenLock || toTokenLock} checked={autoStakePosition} onChange={handleChangeAutoStake} />
                      )} */}
                    </>
                  )}
                </VStack>
              )}

              {/* {apiPoolInfo?.haveFarming && (
                <AutoStakePosition disabled={fromTokenLock || toTokenLock} checked={autoStakePosition} onChange={handleChangeAutoStake} />
              )} */}
            </VStack>
          </VStack>

          <>
            {/* {apiPoolInfo?.vaultCategory && (
              <VaultBanner
                displayTokenA={selectTokenA}
                displayTokenB={selectTokenB}
                feeDisplay={apiPoolInfo?.feeDisplay}
                clmmPool={apiPoolInfo?.poolAddress}
                vaultId={apiPoolInfo?.vaultId}
                isReverse={apiPoolInfo?.isReverse}
                category={apiPoolInfo?.vaultCategory}
              />
            )} */}
          </>
        </VStack>
      </HStack>
    </>
  )
}

export default PCDeposit
