import TotalAmount from '@/components/common/TotalAmount'
import RangeAlerts from '@/components/position/clmm/details/RangeAlerts'
import PositionStatus from '@/components/position/common/PositionStatus'
import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore from '@/store/dlmm/addDlmmLiquidity'
import { Block, TradeConfirmAmountInfo } from '@cetus/design'
import useNotifiStore from '@cetus/stores/src/notifi'
import { Token } from '@cetus/types'
import { CoinPairImage, HTextLabelBox, Icon } from '@cetus/ui-kit'
import { d, formatNumberWithDown, textEllipses } from '@cetus/utils'
import {
  Box,
  Button,
  Divider,
  Heading,
  HStack,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalHeader,
  ModalOverlay,
  Text,
  VStack
} from '@chakra-ui/react'
import { debounce } from 'lodash-es'
import { useMemo, useState } from 'react'

type DLMMAddLiquidityConfirmModalProps = {
  onClose: () => void
  onSubmit: () => void
  data: {
    baseFee?: {
      title: string
      feeDisplay: string
      feeRate: string
      poolAddress: string
      tvl: string
    }
  }
}

export default function DLMMAddLiquidityConfirmModal(props: DLMMAddLiquidityConfirmModalProps) {
  const {
    onClose,
    onSubmit,
    data: { baseFee }
  } = props
  const { fromToken, toToken, fromAmount, toAmount, byAmountIn, totalAmount, fromTokenLock, toTokenLock, minPriceData, maxPriceData, positionCount } =
    useAddDlmmLiquidityStore()
  const { dlmmApiPoolInfo, currentPrice } = useDlmmLiquidityStore()
  const { setIsChecked } = useNotifiStore()
  const [direct, setDirect] = useState(true)
  const showReverse = useMemo(() => {
    if (dlmmApiPoolInfo?.coin_type_a === fromToken?.coin_type) {
      if (direct) {
        return false
      } else {
        return true
      }
    } else {
      if (direct) {
        return true
      } else {
        return false
      }
    }
  }, [dlmmApiPoolInfo, fromToken, toToken, direct])

  const perText = useMemo(() => {
    return direct
      ? `${textEllipses(toToken?.symbol, 10)} per ${textEllipses(fromToken?.symbol, 10)}`
      : `${textEllipses(fromToken?.symbol, 10)} per ${textEllipses(toToken?.symbol)}`
  }, [direct, fromToken?.symbol, toToken?.symbol])

  const onOk = debounce(
    () => {
      onSubmit()
      onClose()
    },
    1000,
    {
      leading: true,
      trailing: false
    }
  )

  const { notifiStatus } = useNotifiStore()

  const isActive = !fromTokenLock && !toTokenLock
  return (
    <Modal
      isOpen={true}
      onClose={() => {
        onClose()
        setIsChecked(false)
      }}
      isCentered
    >
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Add Liquidity
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody textAlign="center" p="0px">
          <VStack w="100%" gap="20px" p="8px 16px" pb="0px">
            <HStack w="100%" justifyContent="space-between" h="40px">
              <HStack>
                <CoinPairImage
                  coinACoinType={fromToken?.coin_type}
                  coinBCoinType={toToken?.coin_type}
                  coinAIconUrl={fromToken?.logo_url}
                  coinBIconUrl={toToken?.logo_url}
                  imageStyle={{
                    w: '40px',
                    h: '40px'
                  }}
                  imgBoxStyle={{
                    w: '40px',
                    h: '40px'
                  }}
                />
                <Text fontSize="16px" color="text_caption" textAlign="left">
                  {`${textEllipses(fromToken?.symbol, 10)} - ${textEllipses(toToken?.symbol, 10)}`}
                </Text>
              </HStack>

              <Block w="unset" p="8px 12px" borderRadius="12px" ml="4px">
                <HStack gap="12px">
                  <Text whiteSpace="nowrap">Base Fee</Text>
                  <Text color="primary_green">
                    {d(baseFee)
                      .div(10 ** 6)
                      .toString()}
                    %
                  </Text>
                </HStack>
              </Block>
            </HStack>

            {/* 交易数量展示 */}
            <TradeConfirmAmountInfo
              coinA={{
                amount: fromAmount as string,
                ...(fromToken as Token)
              }}
              coinB={{
                amount: toAmount as string,
                ...(toToken as Token)
              }}
            />
            <Box w="100%">
              <HStack w="100%" justify="space-between" h="32px">
                <Text fontSize="16px" fontWeight="500" color="text_caption">
                  Selected Range
                </Text>
                <PositionStatus isActive={isActive} isRow imgStyle={{ imgW: '29px', imgH: '16px' }} w="105px" h="32px" />
              </HStack>
              <VStack gap="0" border="1px solid" bg="bg_secondary" borderColor="border" borderRadius="12px" mt="8px">
                <HStack justify="center" h="48px" w="100%" gap="4px">
                  <Text>Current Price</Text>
                  <Text as="span" color="text_caption">
                    {formatNumberWithDown(showReverse ? d(1).div(currentPrice).toString() : currentPrice, 6)}
                  </Text>
                  <Text>{perText}</Text>
                  <Button variant="unstyled" onClick={() => setDirect(!direct)}>
                    <Icon xlinkHref="#icon-icon_swap1" />
                  </Button>
                </HStack>
                <Box h="1px" w="calc(100% - 32px)" p="0 12px" bg="border" />
                <HStack w="100%" h="100px">
                  <PriceItem
                    title="Min Price"
                    price={formatNumberWithDown(showReverse ? d(1).div(minPriceData?.price).toString() : minPriceData?.price, 6)}
                    perText={perText}
                  />
                  <Divider orientation="vertical" h="40px" />
                  <PriceItem
                    title="Max Price"
                    price={formatNumberWithDown(showReverse ? d(1).div(maxPriceData?.price).toString() : maxPriceData?.price, 6)}
                    perText={perText}
                  />
                </HStack>
              </VStack>
            </Box>

            <HTextLabelBox label="Position" value={positionCount} labelStyle={{ fontSize: '14px' }} valueStyle={{ fontSize: '14px' }} />
            <TotalAmount loading={false} totalAmount={totalAmount} />

            {!fromTokenLock && !toTokenLock && !(minPriceData?.price === '0' && maxPriceData?.price === '∞') && notifiStatus == 'authenticated' && (
              <RangeAlerts
                subscriptionSource="AddLiquidity"
                title="Range alerts for this position"
                description="Subscribe to receive alerts on email, SMS, or Telegram when the price for this pool moves out of your selected range."
                wrapStyle={{
                  bg: 'bg_secondary',
                  borderRadius: '12px'
                }}
              />
            )}
            <Button w="calc(100% + 32px)" bottom="0px" mt="4px" h="52px" borderRadius="12px" fontSize="16px" fontWeight="500" onClick={onOk}>
              Add Liquidity
            </Button>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}

const PriceItem = ({ title, price, perText }: { title: string; price: string; perText: string }) => {
  return (
    <VStack flex="1">
      <Text>{title}</Text>
      <Text color="text_caption">{price}</Text>
      <Text>{perText}</Text>
    </VStack>
  )
}
